 52→void UW_TitleScreen::NativeConstruct()
 53→{
 54→    Super::NativeConstruct();
 55→
 56→    // Apply colors
 57→    if (BackgroundBorder)
 58→    {
 59→        BackgroundBorder->SetBrushColor(BackgroundColor);
 60→    }
 61→    if (TitleText)
 62→    {
