 94→void UW_TitleScreen::NativeTick(const FGeometry& MyGeometry, float InDeltaTime)
 95→{
 96→    Super::NativeTick(MyGeometry, InDeltaTime);
 97→
 98→    // Pulse the "Press ENTER to begin" text opacity
 99→    PulseTimer += InDeltaTime;
100→    if (PromptText)
101→    {
102→        // Sine wave oscillation between 0.3 and 1.0
103→        float Alpha = 0.3f + 0.7f * (0.5f + 0.5f * FMath::Sin(PulseTimer * 2.5f));
104→        PromptText->SetRenderOpacity(Alpha);
105→    }
106→}
