109→FReply UW_TitleScreen::NativeOnKeyDown(const FGeometry& InGeometry, const FKeyEvent& InKeyEvent)
110→{
111→    if (!bStartRequested)
112→    {
113→        FKey Key = InKeyEvent.GetKey();
114→        if (Key == EKeys::Enter || Key == EKeys::SpaceBar)
115→        {
116→            bStartRequested = true;
117→            UE_LOG(LogTranslatorsBridge, Log, TEXT("[W_TitleScreen] Start requested!"));
118→            OnStartRequested.Broadcast();
119→            return FReply::Handled();
120→        }
121→    }
122→
123→    return Super::NativeOnKeyDown(InGeometry, InKeyEvent);
124→}
