138→void UW_TitleScreen::BuildWidgetTree()
139→{
140→    // Simple structure: Border (root, fills viewport) -> centered VerticalBox -> TextBlocks
141→    // Avoids CanvasPanel AutoSize issues that can collapse to zero
142→    BackgroundBorder = WidgetTree->ConstructWidget<UBorder>(UBorder::StaticClass(), TEXT("BackgroundBorder"));
143→    BackgroundBorder->SetBrushColor(BackgroundColor);
144→    BackgroundBorder->SetHorizontalAlignment(HAlign_Center);
145→    BackgroundBorder->SetVerticalAlignment(VAlign_Center);
146→    BackgroundBorder->SetPadding(FMargin(40.0f));
147→    WidgetTree->RootWidget = BackgroundBorder;
148→
149→    // Content box (centered by border alignment)
150→    UVerticalBox* ContentBox = WidgetTree->ConstructWidget<UVerticalBox>(UVerticalBox::StaticClass(), TEXT("ContentBox"));
151→    BackgroundBorder->AddChild(ContentBox);
152→
153→    // === Title: "The Translators" ===
154→    TitleText = WidgetTree->ConstructWidget<UTextBlock>(UTextBlock::StaticClass(), TEXT("TitleText"));
155→    TitleText->SetText(NSLOCTEXT("TranslatorsBridge", "TitleScreen.Title", "The Translators"));
156→    TitleText->SetColorAndOpacity(FSlateColor(TitleColor));
157→    TitleText->SetJustification(ETextJustify::Center);
158→    TitleText->SetFont(MakeFont(56));
159→
160→    UVerticalBoxSlot* TitleSlot = ContentBox->AddChildToVerticalBox(TitleText);
161→    if (TitleSlot)
162→    {
163→        TitleSlot->SetPadding(FMargin(0.0f, 0.0f, 0.0f, 12.0f));
164→        TitleSlot->SetHorizontalAlignment(HAlign_Center);
165→    }
166→
167→    // === Subtitle: "A cognitive profiling experience" ===
168→    SubtitleText = WidgetTree->ConstructWidget<UTextBlock>(UTextBlock::StaticClass(), TEXT("SubtitleText"));
169→    SubtitleText->SetText(NSLOCTEXT("TranslatorsBridge", "TitleScreen.Subtitle", "A cognitive profiling experience"));
170→    SubtitleText->SetColorAndOpacity(FSlateColor(SubtitleColor));
171→    SubtitleText->SetJustification(ETextJustify::Center);
172→    SubtitleText->SetFont(MakeFont(18));
173→
174→    UVerticalBoxSlot* SubtitleSlot = ContentBox->AddChildToVerticalBox(SubtitleText);
175→    if (SubtitleSlot)
176→    {
177→        SubtitleSlot->SetPadding(FMargin(0.0f, 0.0f, 0.0f, 60.0f));
178→        SubtitleSlot->SetHorizontalAlignment(HAlign_Center);
179→    }
180→
181→    // === Prompt: "Press ENTER to begin" ===
182→    PromptText = WidgetTree->ConstructWidget<UTextBlock>(UTextBlock::StaticClass(), TEXT("PromptText"));
183→    PromptText->SetText(NSLOCTEXT("TranslatorsBridge", "TitleScreen.Prompt", "Press ENTER to begin"));
184→    PromptText->SetColorAndOpacity(FSlateColor(PromptColor));
185→    PromptText->SetJustification(ETextJustify::Center);
186→    PromptText->SetFont(MakeFont(16));
187→
188→    UVerticalBoxSlot* PromptSlot = ContentBox->AddChildToVerticalBox(PromptText);
189→    if (PromptSlot)
190→    {
191→        PromptSlot->SetHorizontalAlignment(HAlign_Center);
192→    }
193→
194→    UE_LOG(LogTranslatorsBridge, Log, TEXT("[W_TitleScreen] Built programmatic widget tree (Border root)"));
195→}
