 36→void UW_OptionButton::NativeConstruct()
 37→{
 38→    Super::NativeConstruct();
 39→
 40→    // Bind button events if button exists
 41→    if (OptionButton)
 42→    {
 43→        OptionButton->OnClicked.AddDynamic(this, &UW_OptionButton::HandleButtonClicked);
 44→        OptionButton->OnHovered.AddDynamic(this, &UW_OptionButton::HandleButtonHovered);
 45→        OptionButton->OnUnhovered.AddDynamic(this, &UW_OptionButton::HandleButtonUnhovered);
 46→    }
 47→
 48→    // Set initial visual state
 49→    UpdateVisualState(NormalColor);
 50→
 51→    // Set label text if available
 52→    if (OptionLabel && !LabelText.IsEmpty())
 53→    {
 54→        OptionLabel->SetText(LabelText);
 55→        OptionLabel->SetColorAndOpacity(FSlateColor(TextColor));
