141→void UW_OptionButton::UpdateVisualState(const FLinearColor& BackgroundColor)
142→{
143→    if (ButtonBorder)
144→    {
145→        ButtonBorder->SetBrushColor(BackgroundColor);
146→    }
147→    else if (OptionButton)
148→    {
149→        // Fallback: tint the button itself
150→        FButtonStyle Style = OptionButton->GetStyle();
151→        Style.Normal.TintColor = FSlateColor(BackgroundColor);
152→        Style.Hovered.TintColor = FSlateColor(HoveredColor);
153→        Style.Pressed.TintColor = FSlateColor(PressedColor);
154→        OptionButton->SetStyle(Style);
155→    }
