159→void UW_OptionButton::BuildWidgetTree()
160→{
161→    // Create border as root (for background color)
162→    ButtonBorder = WidgetTree->ConstructWidget<UBorder>(UBorder::StaticClass(), TEXT("ButtonBorder"));
163→    ButtonBorder->SetBrushColor(NormalColor);
164→    ButtonBorder->SetPadding(FMargin(20.0f, 12.0f));
165→    WidgetTree->RootWidget = ButtonBorder;
166→
167→    // Create size box to ensure consistent button size
168→    USizeBox* ButtonSizeBox = WidgetTree->ConstructWidget<USizeBox>(USizeBox::StaticClass(), TEXT("ButtonSizeBox"));
169→    ButtonSizeBox->SetMinDesiredWidth(400.0f);
170→    ButtonSizeBox->SetMinDesiredHeight(50.0f);
171→    ButtonBorder->AddChild(ButtonSizeBox);
172→
173→    // Create the actual button (invisible, just for interaction)
174→    OptionButton = WidgetTree->ConstructWidget<UButton>(UButton::StaticClass(), TEXT("OptionButton"));
175→
176→    // Make button transparent - border handles visuals
177→    FButtonStyle TransparentStyle;
178→    TransparentStyle.Normal.TintColor = FSlateColor(FLinearColor::Transparent);
179→    TransparentStyle.Hovered.TintColor = FSlateColor(FLinearColor::Transparent);
180→    TransparentStyle.Pressed.TintColor = FSlateColor(FLinearColor::Transparent);
181→    OptionButton->SetStyle(TransparentStyle);
182→
183→    ButtonSizeBox->AddChild(OptionButton);
184→
185→    // Create label text
186→    OptionLabel = WidgetTree->ConstructWidget<UTextBlock>(UTextBlock::StaticClass(), TEXT("OptionLabel"));
187→    OptionLabel->SetText(LabelText.IsEmpty() ? NSLOCTEXT("TranslatorsBridge", "OptionButton.Default", "Option") : LabelText);
188→    OptionLabel->SetColorAndOpacity(FSlateColor(TextColor));
189→    OptionLabel->SetJustification(ETextJustify::Center);
190→    OptionLabel->SetAutoWrapText(true);
191→
192→    OptionLabel->SetFont(FSlateFontInfo(FPaths::EngineContentDir() / TEXT("Slate/Fonts/Roboto-Regular.ttf"), 18));
193→
194→    OptionButton->AddChild(OptionLabel);
195→
196→    UE_LOG(LogTranslatorsBridge, Log, TEXT("[W_OptionButton] Built programmatic widget tree"));
197→}
