 69→void UW_QuestionDisplay::BuildWidgetTree()
 70→{
 71→    // Create root canvas
 72→    UCanvasPanel* RootCanvas = WidgetTree->ConstructWidget<UCanvasPanel>(UCanvasPanel::StaticClass(), TEXT("RootCanvas"));
 73→    WidgetTree->RootWidget = RootCanvas;
 74→
 75→    // Create background border - centered panel
 76→    BackgroundBorder = WidgetTree->ConstructWidget<UBorder>(UBorder::StaticClass(), TEXT("BackgroundBorder"));
 77→    BackgroundBorder->SetBrushColor(BackgroundColor);
 78→    BackgroundBorder->SetPadding(FMargin(40.0f, 30.0f));
 79→
 80→    UCanvasPanelSlot* BorderSlot = RootCanvas->AddChildToCanvas(BackgroundBorder);
 81→    if (BorderSlot)
 82→    {
 83→        // Center the panel
 84→        BorderSlot->SetAnchors(FAnchors(0.5f, 0.5f, 0.5f, 0.5f));
 85→        BorderSlot->SetAlignment(FVector2D(0.5f, 0.5f));
 86→        BorderSlot->SetAutoSize(true);
 87→    }
 88→
 89→    // Create main vertical layout
 90→    UVerticalBox* MainLayout = WidgetTree->ConstructWidget<UVerticalBox>(UVerticalBox::StaticClass(), TEXT("MainLayout"));
 91→    BackgroundBorder->AddChild(MainLayout);
 92→
 93→    // Create size box to constrain width
 94→    USizeBox* ContentSizeBox = WidgetTree->ConstructWidget<USizeBox>(USizeBox::StaticClass(), TEXT("ContentSizeBox"));
 95→    ContentSizeBox->SetWidthOverride(600.0f);
 96→    UVerticalBoxSlot* SizeBoxSlot = MainLayout->AddChildToVerticalBox(ContentSizeBox);
 97→    if (SizeBoxSlot)
 98→    {
 99→        SizeBoxSlot->SetHorizontalAlignment(HAlign_Center);
100→    }
101→
102→    // Inner vertical box for content
103→    UVerticalBox* ContentBox = WidgetTree->ConstructWidget<UVerticalBox>(UVerticalBox::StaticClass(), TEXT("ContentBox"));
104→    ContentSizeBox->AddChild(ContentBox);
105→
106→    // Depth label (top - e.g. "SURFACE", "PATTERNS", etc.)
107→    DepthText = WidgetTree->ConstructWidget<UTextBlock>(UTextBlock::StaticClass(), TEXT("DepthText"));
108→    DepthText->SetText(NSLOCTEXT("TranslatorsBridge", "QuestionDisplay.DefaultDepth", "SURFACE"));
109→    DepthText->SetColorAndOpacity(FSlateColor(DepthLabelColor));
110→    DepthText->SetJustification(ETextJustify::Center);
111→
112→    DepthText->SetFont(MakeFont(12));
113→
114→    UVerticalBoxSlot* DepthSlot = ContentBox->AddChildToVerticalBox(DepthText);
115→    if (DepthSlot)
116→    {
117→        DepthSlot->SetPadding(FMargin(0.0f, 0.0f, 0.0f, 8.0f));
118→        DepthSlot->SetHorizontalAlignment(HAlign_Center);
119→    }
120→
121→    // Progress text
122→    ProgressText = WidgetTree->ConstructWidget<UTextBlock>(UTextBlock::StaticClass(), TEXT("ProgressText"));
123→    ProgressText->SetText(NSLOCTEXT("TranslatorsBridge", "QuestionDisplay.DefaultProgress", "1 / 8"));
124→    ProgressText->SetColorAndOpacity(FSlateColor(ProgressTextColor));
125→    ProgressText->SetJustification(ETextJustify::Center);
126→
127→    ProgressText->SetFont(MakeFont(14));
128→
129→    UVerticalBoxSlot* ProgressSlot = ContentBox->AddChildToVerticalBox(ProgressText);
130→    if (ProgressSlot)
131→    {
132→        ProgressSlot->SetPadding(FMargin(0.0f, 0.0f, 0.0f, 20.0f));
133→        ProgressSlot->SetHorizontalAlignment(HAlign_Center);
134→    }
135→
136→    // Question text (center)
137→    QuestionText = WidgetTree->ConstructWidget<UTextBlock>(UTextBlock::StaticClass(), TEXT("QuestionText"));
138→    QuestionText->SetText(NSLOCTEXT("TranslatorsBridge", "QuestionDisplay.Loading", "Loading question..."));
139→    QuestionText->SetColorAndOpacity(FSlateColor(QuestionTextColor));
140→    QuestionText->SetJustification(ETextJustify::Center);
141→    QuestionText->SetAutoWrapText(true);
142→
143→    QuestionText->SetFont(MakeFont(24));
144→
145→    UVerticalBoxSlot* QuestionSlot = ContentBox->AddChildToVerticalBox(QuestionText);
146→    if (QuestionSlot)
147→    {
148→        QuestionSlot->SetPadding(FMargin(0.0f, 0.0f, 0.0f, 30.0f));
149→        QuestionSlot->SetHorizontalAlignment(HAlign_Fill);
150→    }
151→
