124→void UW_ProgressIndicator::RefreshIndicators()
125→{
126→    // Update indicator colors
127→    for (int32 i = 0; i < IndicatorImages.Num(); i++)
128→    {
129→        UImage* Indicator = IndicatorImages[i];
130→        if (!Indicator) continue;
131→
132→        FLinearColor Color;
133→        if (i < CurrentQuestion)
134→        {
135→            // Completed
136→            Color = CompletedColor;
137→        }
138→        else if (i == CurrentQuestion)
139→        {
140→            // Current (in progress)
141→            Color = CurrentColor;
142→        }
143→        else
144→        {
145→            // Not yet reached
146→            Color = IncompleteColor;
147→        }
148→
149→        Indicator->SetColorAndOpacity(Color);
150→    }
151→
152→    // Update text label
153→    if (ProgressLabel)
154→    {
155→        FString LabelText = FString::Printf(TEXT("%d / %d"), CurrentQuestion, TotalQuestions);
156→        ProgressLabel->SetText(FText::FromString(LabelText));
157→    }
158→}
